module file_matcher (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] pattern_char,\n    input [7:0] filename_char,\n    input pattern_valid,\n    input filename_valid,\n    input pattern_end,\n    input filename_end,\n    output reg match,\n    output reg done\n);\n\n// Parameters\nlocalparam MAX_LEN = 16;\n\n// State machine states\nlocalparam [2:0] IDLE = 3'd0;\nlocalparam [2:0] MATCH = 3'd1;\nlocalparam [2:0] CHECK_STAR = 3'd2;\nlocalparam [2:0] ADVANCE_BOTH = 3'd3;\nlocalparam [2:0] ADVANCE_PATTERN = 3'd4;\nlocalparam [2:0] ADVANCE_FILENAME = 3'd5;\nlocalparam [2:0] BACKTRACK = 3'd6;\nlocalparam [2:0] DONE_STATE = 3'd7;\n\n// Registers\nreg [2:0] state, next_state;\nreg [7:0] pattern_reg [0:MAX_LEN-1];\nreg [7:0] filename_reg [0:MAX_LEN-1];\nreg [4:0] pattern_idx;\nreg [4:0] filename_idx;\nreg [4:0] star_idx;\nreg [4:0] star_match_idx;\nreg [4:0] pattern_len;\nreg [4:0] filename_len;\nreg processing;\ninteger i;\n\n// State transition\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n    end else begin\n        state <= next_state;\n    end\nend\n\n// Next state logic\nalways @(*) begin\n    next_state = state;\n    case (state)\n        IDLE: begin\n            if (start && pattern_valid && filename_valid) begin\n                next_state = MATCH;\n            end\n        end\n        MATCH: begin\n            if ((pattern_idx == pattern_len) && (filename_idx == filename_len)) begin\n                next_state = DONE_STATE;\n            end else if (pattern_idx == pattern_len) begin\n                next_state = DONE_STATE;\n            end else if (filename_idx == filename_len) begin\n                if (pattern_reg[pattern_idx] == 8'd42) begin\n                    next_state = ADVANCE_PATTERN;\n                end else begin\n                    next_state = DONE_STATE;\n                end\n            end else if (pattern_reg[pattern_idx] == 8'd42) begin\n                next_state = CHECK_STAR;\n            end else if ((pattern_reg[pattern_idx] == filename_reg[filename_idx]) || \n                       (pattern_reg[pattern_idx] == 8'd63)) begin\n                next_state = ADVANCE_BOTH;\n            end else if (star_idx != 5'd31) begin\n                next_state = BACKTRACK;\n            end else begin\n                next_state = DONE_STATE;\n            end\n        end\n        CHECK_STAR: begin\n            next_state = ADVANCE_PATTERN;\n        end\n        ADVANCE_BOTH: begin\n            next_state = MATCH;\n        end\n        ADVANCE_PATTERN: begin\n            next_state = MATCH;\n        end\n        ADVANCE_FILENAME: begin\n            next_state = MATCH;\n        end\n        BACKTRACK: begin\n            next_state = MATCH;\n        end\n        DONE_STATE: begin\n            if (!start) begin\n                next_state = IDLE;\n            end\n        end\n        default: next_state = IDLE;\n    endcase\nend\n\n// Output and datapath logic\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        pattern_idx <= 5'd0;\n        filename_idx <= 5'd0;\n        star_idx <= 5'd31;\n        star_match_idx <= 5'd0;\n        match <= 1'b0;\n        done <= 1'b0;\n        processing <= 1'b0;\n        pattern_len <= 5'd0;\n        filename_len <= 5'd0;\n        for (i = 0; i < MAX_LEN; i = i + 1) begin\n            pattern_reg[i] <= 8'd0;\n            filename_reg[i] <= 8'd0;\n        end\n    end else begin\n        case (state)\n            IDLE: begin\n                match <= 1'b0;\n                done <= 1'b0;\n                if (start && pattern_valid && filename_valid) begin\n                    processing <= 1'b1;\n                    pattern_len <= 5'd0;\n                    filename_len <= 5'd0;\n                    pattern_idx <= 5'd0;\n                    filename_idx <= 5'd0;\n                    star_idx <= 5'd31;\n                    star_match_idx <= 5'd0;\n                end\n            end\n            MATCH: begin\n                // Buffer inputs if valid and space available\n                if (pattern_valid && processing && (pattern_len < MAX_LEN)) begin\n                    pattern_reg[pattern_len] <= pattern_char;\n                    pattern_len <= pattern_len + 5'd1;\n                end\n                if (filename_valid && processing && (filename_len < MAX_LEN)) begin\n                    filename_reg[filename_len] <= filename_char;\n                    filename_len <= filename_len + 5'd1;\n                end\n            end\n            CHECK_STAR: begin\n                star_idx <= pattern_idx;\n                star_match_idx <= filename_idx;\n                pattern_idx <= pattern_idx + 5'd1;\n            end\n            ADVANCE_BOTH: begin\n                pattern_idx <= pattern_idx + 5'd1;\n                filename_idx <= filename_idx + 5'd1;\n            end\n            ADVANCE_PATTERN: begin\n                if (pattern_idx < pattern_len) begin\n                    pattern_idx <= pattern_idx + 5'd1;\n                end\n            end\n            ADVANCE_FILENAME: begin\n                if (filename_idx < filename_len) begin\n                    filename_idx <= filename_idx + 5'd1;\n                end\n            end\n            BACKTRACK: begin\n                pattern_idx <= star_idx + 5'd1;\n                filename_idx <= star_match_idx + 5'd1;\n                star_match_idx <= star_match_idx + 5'd1;\n            end\n            DONE_STATE: begin\n                done <= 1'b1;\n                match <= ((pattern_idx == pattern_len) && (filename_idx == filename_len)) ? 1'b1 : 1'b0;\n                processing <= 1'b0;\n            end\n        endcase\n    end\nend\n\nendmodule